#include "sh1122.h"

struct sh1122_dev sh1122;

/* -----------------------------------------------------------------------
 * sh1122Init
 *
 * Minimal bring-up sequence.  Display remains off until sh1122TurnDisplayOn().
 * ----------------------------------------------------------------------- */
void sh1122Init()
{
    sh1122Cmd_SetDisplayOn(0);
    sh1122Cmd_SetOscFrequency(1, 5);
//    sh1122Cmd_SetMultiplexRatio(64);
//    sh1122Cmd_SetDisplayStartLine(0);
//    sh1122Cmd_SetDisplayOffset(0);
    sh1122Cmd_SetVSL();
    sh1122Cmd_SetContrast(0x80);
    sh1122Cmd_SetPreChargePeriod(2, 2);
    sh1122Cmd_SetVCOMDeselectLevel(0x35);
    sh1122Cmd_SetChargePump(1);
//    sh1122Cmd_EntireDisplayOn(0);
//    sh1122Cmd_SetInverseDisplay(0);
}

/* -----------------------------------------------------------------------
 * sh1122FlipScreen
 *
 * flip=1 → orientation used by most common 256x64 modules.
 * Can be removed if screen orientation is fixed in your design.
 * ----------------------------------------------------------------------- */
void sh1122FlipScreen(unsigned int flip)
{
    if (flip) {
        sh1122Cmd_SetSegmentRemap(0);
        sh1122Cmd_SetRowRemap(0);
        sh1122Cmd_SetDisplayStartLine(0);
    } else {
        sh1122Cmd_SetSegmentRemap(1);
        sh1122Cmd_SetRowRemap(1);
        sh1122Cmd_SetDisplayStartLine(0);
    }
}

void sh1122TurnDisplayOn(unsigned int display_on)
{
    sh1122Cmd_SetDisplayOn(display_on);
}

/* -----------------------------------------------------------------------
 * sh1122ClearScreen
 *
 * Fills GDDRAM with 0x00 directly and resets both software buffers.
 * ----------------------------------------------------------------------- */
void sh1122ClearScreen()
{
    struct sh1122_dev *disp = &sh1122;
    unsigned char row_buf[DISPLAY_BYTE_WIDTH];  // 128 bytes only
    int row;

    for (int i = 0; i < DISPLAY_BYTE_WIDTH; i++)
        row_buf[i] = 0x00;

    for (row = 0; row < DISPLAY_HEIGHT; row++) {
        sh1122Cmd_SetRowAddress(row);
        sh1122Cmd_SetColumnAddress(0);
        sh1122Cmd_SendData(row_buf, DISPLAY_BYTE_WIDTH);
    }

    // Clear software buffers using the global struct, not a local 8K buffer
    memset(disp->stagingBuffer, 0x00, DISPLAY_BUF_SIZE);
    memset(disp->displayBuffer, 0x00, DISPLAY_BUF_SIZE);
}

void sh1122LoadSplashScreen()
{
    struct sh1122_dev *disp = &sh1122;
    memcpy(disp->stagingBuffer, &splash_buffer, sizeof(disp->stagingBuffer));
}

void sh1122UpdateStagingScreen()
{
    struct sh1122_dev *disp = &sh1122;

    sh1122CalcUpdateRect();
    sh1122Render();

    memcpy(&disp->displayBuffer, &disp->stagingBuffer, sizeof(disp->displayBuffer));
}

/* -----------------------------------------------------------------------
 * sh1122CalcUpdateRect
 *
 * Computes the minimal dirty rectangle by XOR-ing staging vs display buffer.
 * ----------------------------------------------------------------------- */
void sh1122CalcUpdateRect(void)
{
    struct sh1122_dev *disp = &sh1122;
    int left = -1, right = -1, top = -1, bottom = -1;

    for (int i = 0; i < DISPLAY_BUF_SIZE; i++) {
        if (disp->stagingBuffer[i] ^ disp->displayBuffer[i]) {
            int col = i % DISPLAY_BYTE_WIDTH;
            int row = i / DISPLAY_BYTE_WIDTH;

            if (left  < 0 || col < left)   left   = col;
            if (right < 0 || col > right)  right  = col;
            if (top   < 0 || row < top)    top    = row;
            if (bottom < row)              bottom = row;
        }
    }

    disp->upd_x = left;
    disp->upd_y = top;
    disp->upd_w = (left >= 0) ? (right  - left  + 1) : 0;
    disp->upd_h = (top  >= 0) ? (bottom - top   + 1) : 0;
}

/* -----------------------------------------------------------------------
 * sh1122Render
 *
 * Sends only the dirty rectangle to GDDRAM.
 * ----------------------------------------------------------------------- */
void sh1122Render(void)
{
    struct sh1122_dev *disp = &sh1122;

    if (disp->upd_x < 0 || disp->upd_y < 0 ||
        disp->upd_w <= 0 || disp->upd_h <= 0)
        return;

    for (int row = disp->upd_y; row < disp->upd_y + disp->upd_h; row++) {
        sh1122Cmd_SetRowAddress(row);
        sh1122Cmd_SetColumnAddress(disp->upd_x);
        sh1122Cmd_SendData(
            &disp->stagingBuffer[row * DISPLAY_BYTE_WIDTH + disp->upd_x],
            disp->upd_w
        );
    }
}

/* Force-render the full staging buffer (useful for first frame / debug) */
void sh1122RenderAll(void)
{
    struct sh1122_dev *disp = &sh1122;

    for (int row = 0; row < DISPLAY_HEIGHT; row++) {
        sh1122Cmd_SetRowAddress(row);
        sh1122Cmd_SetColumnAddress(0);
        sh1122Cmd_SendData(&disp->stagingBuffer[row * DISPLAY_BYTE_WIDTH],
                           DISPLAY_BYTE_WIDTH);
    }
}

/* -----------------------------------------------------------------------
 * sh1122UpdateStagingBuffer
 *
 * Copies pre-encoded grayscale bytes directly into the staging buffer
 * at byte-column position (x, row).
 * ----------------------------------------------------------------------- */
void sh1122UpdateStagingBuffer(const unsigned char *buffer,
                                unsigned int x, unsigned int row,
                                unsigned int w)
{
    struct sh1122_dev *disp = &sh1122;

    if (row >= DISPLAY_HEIGHT)
        return;

    memcpy(&disp->stagingBuffer[row * DISPLAY_BYTE_WIDTH + x], buffer, w);
}

/* -----------------------------------------------------------------------
 * sh1122UpdateStagingBufferPix
 *
 * Pixel-accurate staging buffer write.
 * ----------------------------------------------------------------------- */
void sh1122UpdateStagingBufferPix(const unsigned char *buffer,
                                   unsigned int x, unsigned int y,
                                   unsigned int w, bitmap_op_t op)
{
    struct sh1122_dev *disp = &sh1122;
    unsigned int row = y;

    if (row >= DISPLAY_HEIGHT)
        return;

    unsigned char *ptr = &disp->stagingBuffer[row * DISPLAY_BYTE_WIDTH + x];

    if (op == OP_REPLACE) {
        memcpy(ptr, buffer, w);
    } else {
        for (unsigned int i = 0; i < w; i++)
            ptr[i] |= buffer[i];
    }
}

